-- decisions/0180 R2 (swimlanes and locks): a ticket's lane once it's handed off, and the hand-off's note. Add-only, safe to run twice.
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE control_gauge_tasks ADD COLUMN lane VARCHAR(40) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'control_gauge_tasks' AND COLUMN_NAME = 'lane');
PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE control_gauge_tasks ADD COLUMN handoff VARCHAR(400) NOT NULL DEFAULT \'\'', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'control_gauge_tasks' AND COLUMN_NAME = 'handoff');
PREPARE q FROM @s; EXECUTE q; DEALLOCATE PREPARE q;
-- The CEO's queued work (the session manager's order, 2026-11-26), each added once; its lane comes from TeamRoster::lane.
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, rel) SELECT (SELECT IFNULL(MAX(n.id), 0) + 1 FROM control_gauge_tasks n), UTC_TIMESTAMP(), '', 'area:backlog', 'The Scheduler bundle: two jobs to :02, the carry job out of slow, the 6:13 spread', 'fix', 'The Scheduler bundle: two jobs to :02, the carry job out of slow, the 6:13 spread', 'task', '', 'the build session', 0, 'Lead scores and Work order reminders move to :02 (the :17 crowding, jobs.json 2026-11-24); staging_carry_tick is never read as slow while a copy goes in (0171 §5 slow rule, its 4e note; 0165); live''s nine daily jobs at 6:13 are spread (alarm #776, 2026-11-26). In app/lib/Scheduler.php and ControlAlarms.php.', 'the CEO''s brief, 2026-11-26', '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:backlog' AND item = 'The Scheduler bundle: two jobs to :02, the carry job out of slow, the 6:13 spread');
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, rel) SELECT (SELECT IFNULL(MAX(n.id), 0) + 1 FROM control_gauge_tasks n), UTC_TIMESTAMP(), '', 'area:backlog', 'No Undo after an alarm is acknowledged', 'fix', 'No Undo after an alarm is acknowledged', 'task', '', 'the build session', 0, 'CLAUDE.md "Edit or Undo" (#1314) and handoffs/no-undo.md: built on Sync 13:50 UTC 2026-11-24, to be rebuilt on the live copy. Done when no alarm offers Undo (the board, a module card, Pulse) and Pulse''s Reopen leaves the acknowledgement in place. On /admin/config/control.', 'the CEO''s brief, 2026-11-26', '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:backlog' AND item = 'No Undo after an alarm is acknowledged');
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, rel) SELECT (SELECT IFNULL(MAX(n.id), 0) + 1 FROM control_gauge_tasks n), UTC_TIMESTAMP(), '', 'area:backlog', 'Deadlock detection in the Tier 4 review (R3)', 'fix', 'Deadlock detection in the Tier 4 review (R3)', 'task', '', 'the build session', 0, 'decisions/0180 §4 territory 7: the Tier 4 review flags two open tickets citing decisions that disagree; an executive deadlock goes to Tier 5 per §3. Until R3 the word flag stays as it is (piece2-team.md). In app/lib/TeamRunner.php.', 'the CEO''s brief, 2026-11-26', '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:backlog' AND item = 'Deadlock detection in the Tier 4 review (R3)');
-- R1's two long tickets: their full reason kept in goal (a TEXT column), where nobody has written a goal yet; live's why holds 400 characters and kept only the first 400 (live read of control_gauge_tasks, 2026-11-26).
UPDATE control_gauge_tasks SET goal = 'On 2026-11-26 live''s billing_tick (Plans and renewals) and earned_storage_tick have no run at 6:13 MST; Guests'' 30 days at the same minute ran, and both cron lines are there. Alarm #776 tripped at 13:30 UTC and mailed the Founder (a live alarm: staging''s mail is held by Staging::holdMail). Likely the 6:13 burst: nine live daily jobs and staging''s copies at the same minute (Scheduler::syncStaging copies live''s minute) against max_user_connections 25; storage/scheduler-missed.json would show a refused start. No money harm: the next run takes everything due on or before its day. Routed by decisions/0180''s appendix (#1460); the fix to look at goes with the Scheduler bundle after R2: spread the 6:13 starts, staging''s copies at live''s minute + 7.' WHERE gauge = 'area:backlog' AND kind = 'fix' AND item = 'Two 6:13 jobs never started on live (Plans and renewals, Earned storage)' AND (goal IS NULL OR goal = '');
UPDATE control_gauge_tasks SET goal = '#305 to #307 were withdrawn on data drift, state lines, to-do links appearing and slow-page timeouts; #308 (one Scheduler.php change) blocked 22 times on pages it reaches from afar: /admin/auto-imports.php, /admin/cluster-tools.php, /admin/crawler.php and /admin/ecommerce.php, where a section that shows only with data came and went ("Recently published automatically", "Geo-hub", "Technical details" → its links and buttons), and /admin/crawler-review.php at 390, where a long found-on address broke the phone layout (sideways scroll, edges, overlap, a control off the screen), counts that grow with data. The looks are 30 minutes apart while catch-up changes staging''s data: one way to look at is a third before look taken just before the release goes on, with the after look compared only where all three agree, and layout counts read against the page''s own data (the same long value before). Routed by decisions/0180''s appendix (its duties and reporting lines, #1460). The check is paused for four releases only and is back on before any agent-built release and before R2. Done when it passes a clean admin-only release on today''s staging, and the fixture proves it.' WHERE gauge = 'area:backlog' AND kind = 'fix' AND item = 'Before-and-after check: false blocks from staging''s live data' AND (goal IS NULL OR goal = '');
INSERT INTO control_gauge_tasks (id, at, tz, gauge, item, kind, what, bucket, value, who, uid, why, source, rel) SELECT (SELECT IFNULL(MAX(n.id), 0) + 1 FROM control_gauge_tasks n), UTC_TIMESTAMP(), '', 'area:backlog', 'The zip check refuses seed text longer than its column', 'fix', 'The zip check refuses seed text longer than its column', 'task', '', 'the build session', 0, 'R1 wrote two Work tickets whose why ran past control_gauge_tasks.why (VARCHAR(400)); live is not in strict mode, so they were cut, while the bench refused them. A migration''s text longer than its column should fail the zip check (tools/page-audit/zipcheck.py) against the live table''s columns.', 'the session manager, 2026-11-26 (R2''s build)', '' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM control_gauge_tasks WHERE kind = 'fix' AND gauge = 'area:backlog' AND item = 'The zip check refuses seed text longer than its column');
